package com.abhishek.ecommerce.order;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.*;@Entity @Table(name="orders")public class OrderEntity{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;String userId;BigDecimal total;@Enumerated(EnumType.STRING)OrderStatus status;@ElementCollection List<OrderItem>items=new ArrayList<>();public UUID getId(){return id;}public String getUserId(){return userId;}public void setUserId(String v){userId=v;}public BigDecimal getTotal(){return total;}public void setTotal(BigDecimal v){total=v;}public OrderStatus getStatus(){return status;}public void setStatus(OrderStatus v){status=v;}public List<OrderItem>getItems(){return items;}}@Embeddable class OrderItem{String productId;int quantity;BigDecimal unitPrice;public String getProductId(){return productId;}public void setProductId(String v){productId=v;}public int getQuantity(){return quantity;}public void setQuantity(int v){quantity=v;}public BigDecimal getUnitPrice(){return unitPrice;}public void setUnitPrice(BigDecimal v){unitPrice=v;}}